mapper.select:
select ui.id, ui.nick_name as nickName, ui.user_role as userRole, ui.user_photo as userPhoto, ui.user_balance as userBalance, ui.create_time as createTime, ui.user_status as userStatus from user_info ui
and ui.user_role = #{userRole}
and ui.user_status = #{userStatus}
order by ui.create_time desc
